const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','smart-sync.js','engine.js','deck-midi.js','panels.js','rapid-sync-play-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
async function until(fn,label,ms=20000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`,click=s=>{assert($(s),'Missing '+s);$(s).click();},value=(s,v)=>{$(s).value=String(v);};
function base64(b){let s='';for(let n=0;n<b.length;n+=16384)s+=String.fromCharCode(...b.subarray(n,n+16384));return btoa(s);}
function pulseTimes(a,sr){const result=[];let last=-sr;for(let n=0;n<a.length;n++)if(Math.abs(a[n])>.01&&n-last>sr*.1){result.push(n/sr);last=n;}return result;}
function rms(a,sr,from,to){let sum=0;const start=Math.ceil(from*sr),end=Math.floor(to*sr);assert(start>=0&&end<=a.length&&end>start,'Invalid declared window');for(let n=start;n<end;n++)sum+=a[n]**2;return Math.sqrt(sum/(end-start));}
async function pulseBand(b){const c=new OfflineAudioContext(2,b.length,b.sampleRate),s=c.createBufferSource();s.buffer=b;let previous=s;for(let n=0;n<2;n++){const f=c.createBiquadFilter();f.type='highpass';f.frequency.value=2000;f.Q.value=.707;previous.connect(f);previous=f;}previous.connect(c.destination);s.start();return c.startRendering();}
let app;
async function run(){
 const {state,engine}=app;$('#rapid-run').disabled=true;const report={startedAt:new Date().toISOString(),completed:false,criteria:{maximumPulsePhaseSeconds:.01,minimumPairs:5,pausedMaximumRMS:.0001},scope:'Actual GUI and MIDI-editor rapid Smart Sync/Play plus queued double-Play cancellation, existing keylocked secondary. No artificial engine delay; no native/physical/music/full Sync acceptance.',cases:[],errors:[],checks:[]};
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical graph mute');await until(()=>!state.analysis,'Initial analysis');
  for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);
  const sr=48000,duration=24;
  for(let i=0;i<2;i++){const d=state.decks[i],bpm=i?100:120,offset=i?.17:.05,b=engine.ctx.createBuffer(2,sr*duration,sr),a=b.getChannelData(i);Object.assign(d.track,{bpm,grid:offset,gridWarpMarkers:[],gridMarkers:[],duration,analyzed:true});Object.assign(d,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:false,slip:false,stemSlip:'off',sync:false,level:.8});for(let n=0;n<a.length;n++)a[n]=.04*Math.sin(2*Math.PI*(i?550:330)*n/sr);for(let at=offset;at<duration;at+=60/bpm){const first=Math.round(at*sr);for(let n=0;n<576&&first+n<a.length;n++)a[first+n]+=.15*Math.sin(Math.PI*n/576)*Math.sin(2*Math.PI*3000*n/sr);}engine.clearDeckScratchCache(i);engine.buffers.set(d.track.id,b);engine.mix(i,'level',.8);}
  click(button(0,'quantize'));click('[data-panel="settings"]');const setting=$('[data-setting="Sync Mode"]');setting.value='Smart Sync';setting.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');click(button(1,'keylock'));await until(()=>state.decks[1].keylock,'Secondary Keylock');click(button(0,'sync'));click(button(0,'play'));await until(()=>state.decks[0].playing&&!state.decks[0].processing,'Primary Play');
  click('[data-panel="midi"]');click('#midi-reset');for(const [target,n]of [['Deck 2 sync',5],['Deck 2 play',7]]){value('#midi-target',target);value('#midi-type','Note');value('#midi-channel',3);value('#midi-number',n);value('#midi-encoding','7-bit absolute');click('#midi-add');}click('#modal-close');
  const send=(n,v)=>{value('#midi-type','Note');value('#midi-channel',3);value('#midi-number',n);value('#midi-test-value',v);click('#midi-send');};await engine.recordStart();report.recordStart=engine.recordStarted;
  for(const kind of ['gui','midi']){
   const d=state.decks[1];if(d.playing){click(button(1,'play'));await until(()=>!d.playing,'Stop secondary');}click(button(1,'syncOff'));await engine.seek(d,0);
   const c={kind,requestedAt:engine.ctx.currentTime-engine.recordStarted,playsBefore:d.track.plays};report.cases.push(c);
   if(kind==='gui'){click(button(1,'sync'));click(button(1,'play'));}
   else{click('[data-panel="midi"]');send(5,127);send(5,0);send(7,127);send(7,0);click('#modal-close');}
   c.immediateQueued={state:!!d.playQueued,aria:$(button(1,'play')).getAttribute('aria-busy')};
   await until(()=>d.playing&&!d.processing,'Rapid secondary Play');await until(()=>engine.ctx.currentTime>=d.anchorTime+.05,'Scheduled secondary audio');c.started={at:engine.ctx.currentTime-engine.recordStarted,sync:d.sync,state:d.syncState,rate:d.rate,position:engine.position(d),playQueued:!!d.playQueued,plays:d.track.plays};c.from=c.started.at+.35;c.to=c.started.at+3.35;await until(()=>engine.ctx.currentTime>=engine.recordStarted+c.to+.1,'Pulse observation');
  }
  const d=state.decks[1];click(button(1,'play'));await until(()=>!d.playing,'Pause before cancel');click(button(1,'syncOff'));await engine.seek(d,0);report.cancel={at:engine.ctx.currentTime-engine.recordStarted,playsBefore:d.track.plays};click(button(1,'sync'));click(button(1,'play'));click(button(1,'play'));await sleep(600);report.cancel.after={playing:d.playing,processing:d.processing,queued:!!d.playQueued,plays:d.track.plays};report.cancel.from=report.cancel.at+.35;report.cancel.to=report.cancel.at+.55;
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  for(const d of state.decks)engine.pause(d);
  if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};try{const b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:b.duration,frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels};assert(b.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of b.getChannelData(c))assert(Number.isFinite(v),'Nonfinite whole recording');const band=await pulseBand(b),times=[0,1].map(c=>pulseTimes(band.getChannelData(c),b.sampleRate));
   report.audio={pulseMethod:'Two highpass biquads at2000Hz/Q.707; amplitude.01 threshold and100ms refractory. No temporal fitting.',pulseTimes:times};
   for(const c of report.cases){c.pairs=times[0].filter(t=>t>=c.from&&t<=c.to).map(t=>({time:t,errorSeconds:Math.min(...times[1].map(r=>Math.abs(t-r)))}));c.statePassed=c.started.sync&&c.started.state==='beat';c.phasePassed=c.pairs.length>=5&&c.pairs.every(p=>p.errorSeconds<=.01);c.onePlayRecorded=c.started.plays===c.playsBefore+1;}
   if(report.cancel){report.cancel.rightRMS=rms(b.getChannelData(1),b.sampleRate,report.cancel.from,report.cancel.to);report.cancel.passed=!report.cancel.after.playing&&!report.cancel.after.processing&&!report.cancel.after.queued&&report.cancel.after.plays===report.cancel.playsBefore&&report.cancel.rightRMS<.0001;}
   if(report.cases.length===2&&report.cases.every(c=>c.statePassed&&c.phasePassed&&c.onePlayRecorded))report.checks.push('GUI and MIDI rapid Sync/Play reach Beat Sync and one counted playback with aligned audible pulses');else report.errors.push({message:'Rapid Sync/Play state, pulse phase or single-start count failed'});
   if(report.cancel?.passed)report.checks.push('Second Play cancels waiting playback without later audio/history');else report.errors.push({message:'Queued playback cancellation failed'});
  }catch(error){report.errors.push({message:error.message,stack:error.stack});}}}
  report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===2&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#rapid-original').textContent=JSON.stringify(report,null,2);$('#rapid-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in complete original'}:null},null,2);$('#rapid-status').textContent=report.completed?'Scoped rapid Sync/Play workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');const link=$('#rapid-download');link.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));link.download='rapid-sync-play-original.json';link.hidden=false;
 }
}
$('#rapid-run').onclick=()=>run();async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#rapid-run').disabled=false;$('#rapid-run').textContent='Run one rapid Sync/Play workflow';}boot().catch(error=>$('#rapid-status').textContent=error.message);
